class Node {
public:
    void set_local(Transform t) { local_ = t; dirty_ = true; }
    const Transform& world() const {              // const accessor, lazy cache
        if (dirty_) { world_ = local_.combine(parent()); dirty_ = false; }
        return world_;
    }
private:
    Transform local_;
    mutable Transform world_;
    mutable bool dirty_ = true;                   // a fresh node has no cache
};

