class Node {
public:
    void set_local(Transform t) { local_ = t; world_.reset(); }   // invalidate
    const Transform& world() const {
        if (!world_) world_ = local_.combine(parent());           // absent == dirty
        return *world_;
    }
private:
    Transform local_;
    mutable std::optional<Transform> world_;
};

class Node {
public:
    void set_local(Transform t) { std::lock_guard g{mu_}; local_ = t; dirty_.store(true, std::memory_order_release); }
    Transform world() const {
        std::lock_guard g{mu_};                    // cache and flag move together
        if (dirty_.load(std::memory_order_acquire)) { cache_ = local_.combine(parent());
            dirty_.store(false, std::memory_order_release); }   // publish, then clear
        return cache_;
    }
private:
    mutable std::mutex mu_; Transform local_; Transform cache_; std::atomic<bool> dirty_{true};
};
